(7520100, 1201505, 65234, '<td valign="top">I had to look hard to find that 7th camel LOL. Interesting scene.</td>', 'I had to look hard to find that 7th camel LOL. Interesting scene.', '2017-06-24 11:20:21.000000', NULL, 1),
(7520101, 1201400, 65234, '<td valign="top">I love the expressions! Antsy schoolkids perfectly portrayed. This one is fun to explore; makes me smile and remember when my kids were this age. Nit: I would have cloned out that stray elbow on the right. Especially for this challenge where you don''t want an 8th kid in the image.</td>', 'I love the expressions! Antsy schoolkids perfectly portrayed. This one is fun to explore; makes me smile and remember when my kids were this age. Nit: I would have cloned out that stray elbow on the right. Especially for this challenge where you don''t want an 8th kid in the image.', '2017-06-24 11:22:17.000000', NULL, 1),
(7520102, 1201526, 65234, '<td valign="top">You made a fan look interesting!</td>', 'You made a fan look interesting!', '2017-06-24 11:22:51.000000', NULL, 1),
(7520103, 1201488, 65234, '<td valign="top">Very pretty; I like that only one poppy is in focus.</td>', 'Very pretty; I like that only one poppy is in focus.', '2017-06-24 11:23:14.000000', NULL, 1),
(7520104, 1201358, 65234, '<td valign="top">Interesting tones in the light.</td>', 'Interesting tones in the light.', '2017-06-24 11:23:46.000000', NULL, 1),
(7520105, 1201198, 65234, '<td valign="top">Now that''s something you don''t see every day!</td>', 'Now that''s something you don''t see every day!', '2017-06-24 11:24:10.000000', NULL, 1),
(7520106, 1201494, 65234, '<td valign="top">Coolest-looking straws I''ve ever seen! Love the lighting.</td>', 'Coolest-looking straws I''ve ever seen! Love the lighting.', '2017-06-24 11:30:12.000000', NULL, 1),
(7520107, 1201373, 65234, '<td valign="top">Simple, old-fashioned, lovely.</td>', 'Simple, old-fashioned, lovely.', '2017-06-24 11:30:47.000000', NULL, 1),
(7520108, 1201355, 65234, '<td valign="top">Nice find for this challenge.</td>', 'Nice find for this challenge.', '2017-06-24 11:31:28.000000', NULL, 1),
(7520109, 1201186, 65234, '<td valign="top">Ha! Bonus point for your title. The skeletons are nicely positioned to tell the story, and I like the dark and gloomy look and feel.</td>', 'Ha! Bonus point for your title. The skeletons are nicely positioned to tell the story, and I like the dark and gloomy look and feel.', '2017-06-24 11:32:40.000000', NULL, 1),
(7520110, 1201502, 65234, '<td valign="top">Well done for making me take a closer look at an everyday item.</td>', 'Well done for making me take a closer look at an everyday item.', '2017-06-24 11:33:50.000000', NULL, 1),
(7520111, 1201514, 65234, '<td valign="top">Gotta'' love the variety of outfits :-) Each group in their own little world, while the singleton stares daggers at the tourists.</td>', 'Gotta'' love the variety of outfits :-) Each group in their own little world, while the singleton stares daggers at the tourists.', '2017-06-24 11:35:27.000000', NULL, 1),
(7520112, 1201278, 65234, '<td valign="top">Nice assortment of ingredients, well presented.</td>', 'Nice assortment of ingredients, well presented.', '2017-06-24 11:36:22.000000', NULL, 1),
(7520113, 1201456, 65234, '<td valign="top">Really like the timing of the capture and all those pretty sunset (sunrise?) colors and rays. But ... for me the noise in the sky detracts from the scene. I rarely like noise, so I would have done something to reduce it.</td>', 'Really like the timing of the capture and all those pretty sunset (sunrise?) colors and rays. But ... for me the noise in the sky detracts from the scene. I rarely like noise, so I would have done something to reduce it.', '2017-06-24 11:38:44.000000', NULL, 1),
(7520114, 1201517, 65234, '<td valign="top">This one makes my eyes cross!</td>', 'This one makes my eyes cross!', '2017-06-24 11:40:05.000000', NULL, 1),
(7520239, 1201516, 38162, '<td valign="top">That border only detracts from a very good concept. 7.</td>', 'That border only detracts from a very good concept. 7.', '2017-06-25 21:25:27.000000', NULL, 1),
(7520381, 1201488, 10240, '<td valign="top">Nice composition</td>', 'Nice composition', '2017-06-26 15:51:54.000000', NULL, 1),
