(7520383, 1201524, 10240, '<td valign="top">I like the background and the way it shows through the glass.  The repetition of of the pattern is brings the group together and adds interest.</td>', 'I like the background and the way it shows through the glass.  The repetition of of the pattern is brings the group together and adds interest.', '2017-06-26 15:55:04.000000', NULL, 1),
(7520384, 1201456, 10240, '<td valign="top">Very pretty sunset and great job capturing it.  I think it''s more the subject than the 7 people though.</td>', 'Very pretty sunset and great job capturing it.  I think it''s more the subject than the 7 people though.', '2017-06-26 16:01:53.000000', NULL, 1),
(7520386, 1201497, 10240, '<td valign="top">I really like the colors and the reflection, would be interested in seeing this from a lower perspective.</td>', 'I really like the colors and the reflection, would be interested in seeing this from a lower perspective.', '2017-06-26 16:04:17.000000', NULL, 1),
(7520387, 1201198, 10240, '<td valign="top">Nice colors and exposure</td>', 'Nice colors and exposure', '2017-06-26 16:05:19.000000', NULL, 1),
(7520388, 1201521, 10240, '<td valign="top">Nice control of light.</td>', 'Nice control of light.', '2017-06-26 16:06:49.000000', NULL, 1),
